script.setup:
const s=ctx.state,gl=ctx.gl;
s.program=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,"#version 300 es
precision highp float;
#define GLSLIFY 1
in vec2 v_uv;out vec4 outColor;uniform vec2 u_resolution;uniform sampler2D u_image;
uniform float u_density;
uniform float u_width;
float gridFactor (vec2 vBC, float width, float feather) {
  float w1 = width - feather * 0.5;
  vec3 bary = vec3(vBC.x, vBC.y, 1.0 - vBC.x - vBC.y);
  vec3 d = fwidth(bary);
  vec3 a3 = smoothstep(d * w1, d * (w1 + feather), bary);
  return min(min(a3.x, a3.y), a3.z);
}

float gridFactor (vec2 vBC, float width) {
  vec3 bary = vec3(vBC.x, vBC.y, 1.0 - vBC.x - vBC.y);
  vec3 d = fwidth(bary);
  vec3 a3 = smoothstep(d * (width - 0.5), d * (width + 0.5), bary);
  return min(min(a3.x, a3.y), a3.z);
}

void main(){vec2 uv=v_uv,p=(uv*2.-1.)*u_resolution/min(u_resolution.x,u_resolution.y);vec3 color;vec2 q=fract(uv*u_density);if(q.x+q.y>1.)q=1.-q;float f=gridFactor(q,u_width);color=mix(vec3(.92,.69,.4),vec3(.035,.08,.14),f);
outColor=vec4(color,1);}");
